import{_ as a,o,c as i,a2 as r}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"Cómo está hecho","description":"","frontmatter":{},"headers":[],"relativePath":"proyecto/arquitectura.md","filePath":"proyecto/arquitectura.md","lastUpdated":1791064393000}'),t={name:"proyecto/arquitectura.md"};function n(s,e,d,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="como-esta-hecho" tabindex="-1">Cómo está hecho <a class="header-anchor" href="#como-esta-hecho" aria-label="Permalink to &quot;Cómo está hecho&quot;">​</a></h1><p>Tranqui es de código abierto: puedes revisar que hace lo que dice en <a href="https://github.com/fsoftt/Tranqui" target="_blank" rel="noreferrer">GitHub</a>.</p><h2 id="tecnologias" tabindex="-1">Tecnologías <a class="header-anchor" href="#tecnologias" aria-label="Permalink to &quot;Tecnologías&quot;">​</a></h2><div class="stack-grid"><div><strong>App</strong>.NET MAUI para Android, MVVM con CommunityToolkit</div><div><strong>Backend</strong>.NET 10, ASP.NET Core minimal APIs, MediatR 12, FluentValidation</div><div><strong>Datos</strong>PostgreSQL 17 con EF Core 10</div><div><strong>Cuentas</strong>Firebase Authentication, tokens validados en el servidor</div><div><strong>Criptografía</strong>HMAC-SHA256, AES-256-GCM, HKDF</div><div><strong>Pruebas</strong>xUnit v3, Testcontainers, tests de arquitectura</div><div><strong>Despliegue</strong>Docker Compose y Caddy con HTTPS automático</div><div><strong>CI</strong>GitHub Actions: backend, imagen Docker y app Android</div></div><h2 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h2><ul><li><strong>Domain-Driven Design:</strong> el dominio (números, reputación, cuentas) no depende de nada externo.</li><li><strong>Clean Architecture con vertical slices:</strong> cada funcionalidad tiene su comando o consulta, su validador y su handler juntos.</li><li><strong>Tests de arquitectura</strong> que fallan si una capa depende de otra que no debe.</li><li><strong>App.Core:</strong> toda la lógica de la app (decidir qué hacer con una llamada, la sesión, los ViewModels) es .NET puro y se prueba sin emulador.</li></ul><h2 id="privacidad-desde-el-diseno" tabindex="-1">Privacidad desde el diseño <a class="header-anchor" href="#privacidad-desde-el-diseno" aria-label="Permalink to &quot;Privacidad desde el diseño&quot;">​</a></h2><ul><li>El número se normaliza (formato internacional E.164) y se convierte en código <strong>en un solo lugar</strong> del código.</li><li>Los números viajan en el cuerpo de las peticiones, nunca en la URL, para que no queden en registros de acceso.</li><li>Los logs no incluyen números, nombres ni correos.</li><li>Las claves secretas nunca están en el repositorio ni en la base de datos, y se pueden rotar.</li></ul><h2 id="licencia" tabindex="-1">Licencia <a class="header-anchor" href="#licencia" aria-label="Permalink to &quot;Licencia&quot;">​</a></h2><p><a href="https://github.com/fsoftt/Tranqui/blob/main/LICENSE" target="_blank" rel="noreferrer">AGPL-3.0</a>: cualquiera puede usar, estudiar y modificar el código, y quien ofrezca una versión modificada como servicio debe publicar sus cambios.</p>',10)])])}const h=a(t,[["render",n]]);export{p as __pageData,h as default};
